UPDATE public.blog_posts 
SET tldr_fr = 'À Essaouira et Sidi Kaouki, la marée montante et la mi-marée offrent le plus souvent les vagues les plus régulières. L''automne, l''hiver et le printemps concentrent les meilleures houles atlantiques ; en été, il faut surfer tôt le matin avant les alizés. Le Widget Marées & Vents gratuit de One World Morocco donne les pleines et basses mers, le niveau de la mer en direct, le marnage, la température de l''eau, la houle et la période des vagues sur 19 villes du littoral marocain.'
WHERE slug = 'surf-essaouira-sidi-kaouki-marees-saisons';
